$taskExecutableDrift=@(Compare-Object @($taskBefore.binaries | ForEach-Object {$_.path+':'+$_.bytes+':'+$_.sha256} | Sort-Object) @($taskAfter.binaries | ForEach-Object {$_.path+':'+$_.bytes+':'+$_.sha256} | Sort-Object))
