$taskPackages=@(foreach($taskPackage in $taskSelection.reversePackages){$taskRows=@($taskCatalog.rows | Where-Object {$_.status -eq 'matches' -and $_.package -eq $taskPackage});$taskActual=@($taskRows | ForEach-Object {$taskCaseMap[$_.binary+"`t"+$_.test]});[ordered]@{package=$taskPackage;executed=$taskActual.Count;passed=@($taskActual | Where-Object status -in @('PASS','SLOW')).Count;failed=@($taskActual | Where-Object status -notin @('PASS','SLOW')).Count}})
$taskOldFailureMap=@{};foreach($taskFailure in $taskBaseline.runtime.failureSet){$taskOldFailureMap[$taskFailure.binary+"`t"+$taskFailure.test]=$taskFailure}
