$taskRecon=@(foreach($taskFailure in $taskAudit.failureSet){$taskPattern='^\s*(?:FAIL|ABORT)\s+\[.*?\]\s+\(\s*\d+/\d+\)\s+'+[regex]::Escape($taskFailure.binary)+'\s+'+[regex]::Escape($taskFailure.test)+'\s*$';$taskStart=[Array]::FindIndex($taskLines,[Predicate[string]]{param($line) $line -cmatch $taskPattern});if($taskStart -lt 0 -or $taskStart -gt $taskSummary){throw 'Failure has no original diagnostic block'};$taskEnd=$taskSummary;for($taskI=$taskStart+1;$taskI -lt $taskSummary;$taskI++){if($taskLines[$taskI] -cmatch '^\s*(PASS|SLOW|FAIL|ABORT|SKIP|START)\s+\['){$taskEnd=$taskI;break}};$taskStderr=-1;for($taskI=$taskStart+1;$taskI -lt $taskEnd;$taskI++){if($taskLines[$taskI] -cmatch '^\s*stderr\s+[^\w\s]+\s*$'){$taskStderr=$taskI;break}};if($taskStderr -lt 0){throw ('Failure has no original stderr header: '+$taskFailure.test)};$taskDiagnosis=@($taskLines[($taskStderr+1)..($taskEnd-1)] | Where-Object {$_} | Select-Object -First 45);if(-not $taskDiagnosis.Count){throw ('Failure stderr is empty: '+$taskFailure.test)};[ordered]@{binary=$taskFailure.binary;test=$taskFailure.test;line=$taskStart+1;diagnosis=$taskDiagnosis}})
[ordered]@{version=1;run=$taskRun;failures=$taskRecon} | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $taskEvidence ($taskRun+'.failure-recon.json')) -Encoding utf8
